using UnityEngine;

public class SlashAttack : MonoBehaviour
{
    public void Execute(GameObject from, GameObject to)
    {
        int damage = 30;
        to.GetComponent<Stats>().takeDamage(damage);
        Debug.Log(from.name + " slashed " + to.name + ", dealing " + damage + " damage.");
    }
}
